    ui.querySelector('[data-grid]').innerHTML=html;var info=agendaData(sel),pending=rows(sel).filter(function(e){return !e.done;}).length;ui.querySelector('[data-date-head]').textContent=dateLabel(chosen,{weekday:'long',day:'2-digit',month:'long'});ui.querySelector('[data-date-kind]').textContent=info?agendaName(sel)+' · '+info[1]:'Dia útil';ui.querySelector('[data-date-notes]').textContent=pending+' anotações pendentes';
